     <script>
       const state = {
         attemptedSubmit: false
       };

       function createField(options) {
         const {
           id,
           label,
           type,
           name,
           required = false,
           autocomplete,
           placeholder,
           helperText = "",
           value = ""
         } = options;

         const helperId = helperText ? `${id}-help` : "";
         const errorId = `${id}-error`;
         const describedBy = [helperId, errorId].filter(Boolean).join(" ");

