                   autocomplete: "name",
                   placeholder: "Jordan Lee"
                 })}
                 ${createField({
                   id: "email",
                   label: "Email address",
                   type: "email",
                   name: "email",
                   required: true,
                   autocomplete: "email",
                   placeholder: "jordan@example.com"
                 })}
                 ${createField({
                   id: "phone",
                   label: "Phone number",
                   type: "tel",
                   name: "phone",
                   autocomplete: "tel",
                   placeholder: "(555) 123-4567",
                   helperText: "Optional. Use digits with an area code, for example (555) 123-4567 or +1 555 123 4567."
                 })}
                 <div class="actions">
                   <button type="submit">Send message</button>
                 </div>
                 <p class="form-status" id="form-status" aria-live="polite" hidden></p>
               </form>
             </section>
           </div>
         `;
       }

       function App() {
         return ContactForm();
       }

       function getFormElements() {
         const form = document.getElementById("support-form");
         return {
           form,
           fullName: form.elements.namedItem("fullName"),
           email: form.elements.namedItem("email"),
           phone: form.elements.namedItem("phone"),
           status: document.getElementById("form-status")
         };
       }

       function validateField(field) {
         const value = field.value.trim();

         if (field.name === "fullName") {
           if (!value) {
             return "Enter your full name.";
           }
         }

         if (field.name === "email") {
           if (!value) {
             return "Enter your email address.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value)) {
             return "Enter a valid email address.";
           }
         }

         if (field.name === "phone" && value) {
           const phonePattern = /^[+]?[\d()\s-]{7,20}$/;
           if (!phonePattern.test(value)) {
             return "Use a phone number like (555) 123-4567 or +1 555 123 4567.";
           }
         }

         return "";
       }

       function updateFieldState(field, shouldShowError) {
         const errorNode = document.getElementById(`${field.id}-error`);
         const errorMessage = validateField(field);
         const hasError = Boolean(errorMessage) && shouldShowError;

         field.setAttribute("aria-invalid", String(hasError));
         errorNode.hidden = !hasError;
         errorNode.textContent = hasError ? errorMessage : "";

         return errorMessage;
       }

       function handleSubmit(event) {
         event.preventDefault();
         state.attemptedSubmit = true;

         const { form, fullName, email, phone, status } = getFormElements();
         const fields = [fullName, email, phone];
         const messages = fields.map((field) => ({
           field,
           error: updateFieldState(field, true)
         }));

         const firstInvalid = messages.find((entry) => entry.error)?.field;

         if (firstInvalid) {
           status.hidden = false;
           status.textContent = "Please correct the highlighted fields and try again.";
           firstInvalid.focus();
           return;
         }

         status.hidden = false;
         status.textContent = "Thanks. Your support request is ready to send.";
         state.attemptedSubmit = false;
         form.reset();
         fields.forEach((field) => updateFieldState(field, false));
       }

       function handleBlur(event) {
         if (!(event.target instanceof HTMLInputElement)) {
           return;
         }

         const shouldShowError = state.attemptedSubmit || event.target.value.trim().length > 0;
         updateFieldState(event.target, shouldShowError);
